// Matches each row's Tool to an AI Leakage facts card by name or slug and fills in the dated columns.
const cards = $input.first().json.tools || [];
const norm = t => String(t || '').toLowerCase().replace(/\(.*?\)/g, '').trim();
const find = name => {
  const n = norm(name);
  if (!n) return null;
  return cards.find(c => c.tool === n || norm(c.name) === n)
    || cards.find(c => norm(c.name).includes(n) || n.includes(norm(c.name)));
};
return $('Read your tool register').all().map(r => {
  const row = r.json;
  const c = find(row.Tool);
  return { json: {
    Tool: row.Tool,
    'AI Leakage page': c ? c.our_page.replace('utm_source=ail_feed', 'utm_source=n8n').replace('utm_medium=json', 'utm_medium=template_register') : 'Not covered yet',
    'Last re-read at source': c ? (c.last_reviewed || '') : '',
    'Last checked change': c ? (c.last_change_date || 'None recorded') : '',
    'Updated by workflow': new Date().toISOString().slice(0, 10)
  } };
});
